641:impl prost::transfer::AsyncEncodeSink for PendingOnceSink<'_> {
642:    type Error = prost::EncodeError;
643:
644:    type BufMut<'a>
645:        = &'a mut Vec<u8>
646:    where
647:        Self: 'a;
648:
649:    type PayloadState = PendingPayloadState;
650:
651:    fn encode_error(error: prost::EncodeError) -> Self::Error {
652:        error
653:    }
654:
655:    fn buf_mut(&mut self) -> Self::BufMut<'_> {
656:        self.buf
657:    }
658:
659:    fn poll_put_payload(
660:        &mut self,
661:        payload: &[u8],
662:        state: core::pin::Pin<&mut Self::PayloadState>,
663:        cx: &mut core::task::Context<'_>,
664:    ) -> core::task::Poll<Result<(), Self::Error>> {
665:        let state = state.get_mut();
666:        if !state.returned_pending {
667:            state.returned_pending = true;
668:            self.pending_payloads += 1;
669:            cx.waker().wake_by_ref();
670:            return core::task::Poll::Pending;
671:        }
672:
673:        self.buf.put_slice(payload);
674:        self.completed_payloads += 1;
675:        *state = PendingPayloadState::default();
676:        core::task::Poll::Ready(Ok(()))
677:    }
678:}
