728:fn poll_until_ready<F>(future: F) -> (F::Output, usize)
729:where
730:    F: core::future::Future,
731:{
732:    let mut future = std::pin::pin!(future);
733:    let waker = std::task::Waker::noop();
734:    let mut cx = std::task::Context::from_waker(waker);
735:    let mut pending_polls = 0;
736:
737:    loop {
738:        match future.as_mut().poll(&mut cx) {
739:            core::task::Poll::Ready(output) => return (output, pending_polls),
740:            core::task::Poll::Pending => pending_polls += 1,
741:        }
742:    }
