#[derive(Default)]
struct PendingPayloadState {
    returned_pending: bool,
}

#[cfg(feature = "std")]
struct PendingOnceSink<'a> {
    buf: &'a mut Vec<u8>,
    pending_payloads: usize,
    completed_payloads: usize,
}

#[cfg(feature = "std")]
impl<'a> PendingOnceSink<'a> {
    fn new(buf: &'a mut Vec<u8>) -> Self {
        Self {
            buf,
            pending_payloads: 0,
            completed_payloads: 0,
        }
    }
}

#[cfg(feature = "std")]
impl prost::transfer::AsyncEncodeSink for PendingOnceSink<'_> {
    type Error = prost::EncodeError;

    type BufMut<'a>
        = &'a mut Vec<u8>
    where
        Self: 'a;

    type PayloadState = PendingPayloadState;

    fn encode_error(error: prost::EncodeError) -> Self::Error {
        error
    }

    fn buf_mut(&mut self) -> Self::BufMut<'_> {
        self.buf
    }

    fn poll_put_payload(
        &mut self,
        payload: &[u8],
        state: core::pin::Pin<&mut Self::PayloadState>,
        cx: &mut core::task::Context<'_>,
    ) -> core::task::Poll<Result<(), Self::Error>> {
        let state = state.get_mut();
        if !state.returned_pending {
            state.returned_pending = true;
            self.pending_payloads += 1;
            cx.waker().wake_by_ref();
            return core::task::Poll::Pending;
        }

        self.buf.put_slice(payload);
        self.completed_payloads += 1;
        *state = PendingPayloadState::default();
        core::task::Poll::Ready(Ok(()))
    }
}

#[cfg(feature = "std")]
fn assert_pending_async_encode_matches_sync<M>(message: &M) -> usize
where
    M: Message,
{
    let mut expected = Vec::with_capacity(message.encoded_len());
    message.encode(&mut expected).expect("sync encode succeeds");

    let mut actual = Vec::with_capacity(message.encoded_len());
    let mut sink = PendingOnceSink::new(&mut actual);
    let (result, pending_polls) = poll_until_ready(message.encode_raw_async(&mut sink));
    result.expect("async encode succeeds");

    assert_eq!(sink.pending_payloads, pending_polls);
    assert_eq!(sink.completed_payloads, sink.pending_payloads);
    assert_eq!(actual, expected);

    pending_polls
}

#[cfg(feature = "std")]
fn assert_async_encode_matches_sync<M>(message: &M)
where
    M: Message,
{
    let mut expected = Vec::with_capacity(message.encoded_len());
    message.encode(&mut expected).expect("sync encode succeeds");

    let mut actual = Vec::with_capacity(message.encoded_len());
    {
        let mut sink = prost::transfer::BufMutEncodeSink::new(&mut actual);
        poll_ready(message.encode_raw_async(&mut sink)).expect("async encode succeeds");
    }

    assert_eq!(actual, expected);
}

#[cfg(feature = "std")]
fn poll_ready<F>(future: F) -> F::Output
where
    F: core::future::Future,
{
    let (output, pending_polls) = poll_until_ready(future);
    assert_eq!(pending_polls, 0, "CPU async encode returned pending");
    output
}

#[cfg(feature = "std")]
fn poll_until_ready<F>(future: F) -> (F::Output, usize)
where
    F: core::future::Future,
{
    let mut future = std::pin::pin!(future);
    let waker = std::task::Waker::noop();
    let mut cx = std::task::Context::from_waker(waker);
    let mut pending_polls = 0;

    loop {
        match future.as_mut().poll(&mut cx) {
            core::task::Poll::Ready(output) => return (output, pending_polls),
            core::task::Poll::Pending => pending_polls += 1,
        }
    }
}

//! Owned asynchronous transfer APIs for Protocol Buffers messages.
//!
//! The default [`CpuEngine`] preserves prost's existing synchronous encoding
//! behavior while giving callers an owned future-shaped boundary for engines
//! that need to keep message and destination state across `Poll::Pending`.

use alloc::vec::Vec;
...
use crate::{EncodeError, Message};

/// Options that control how a message is encoded by an [`EncodeEngine`].
#[derive(Clone, Copy, Debug, Default, Eq, PartialEq)]
pub struct EncodeOptions { .. }

/// Owned destination storage for an asynchronous encode operation.
///
/// Engines receive the destination by value and borrow its [`BufMut`] view only
/// while writing bytes. Engines that need stronger guarantees can define their
/// own destination type without changing generated message structs.
pub trait EncodeDst { .. }

impl EncodeDst for Vec<u8> { .. }

impl EncodeDst for BytesMut { .. }

/// Mutable destination used by generated asynchronous Prost encoding.
///
/// The sink exposes a short-lived [`BufMut`] view for protobuf structure
/// writes, and a separate payload-copy hook for `string` / `bytes` field
/// contents. The default CPU sink copies payloads immediately; experimental
/// sinks can return [`Poll::Pending`] while an external copy engine initializes
/// the destination bytes.
pub trait AsyncEncodeSink { .. }

/// Cursor for one generated-message poll encoder frame.
#[derive(Clone, Copy, Debug, Default, Eq, PartialEq)]
struct PollEncodeFrame { .. }

/// Universal generated-message state for poll-based async encoding.
pub struct PollEncodeState<S: AsyncEncodeSink> { .. }

impl<S: AsyncEncodeSink> Default for PollEncodeState<S> { .. }

impl<S: AsyncEncodeSink> PollEncodeState<S> { .. }
/// Future-shaped adapter for a single payload copy.
pub struct PutPayload<'a, S: AsyncEncodeSink> { .. }

impl<'a, S: AsyncEncodeSink> PutPayload<'a, S> { .. }

impl<S> Future for PutPayload<'_, S>
where
    S: AsyncEncodeSink + Send,
{ .. }

/// Future-shaped adapter around [`Message::poll_encode_raw`].
pub struct EncodeRawAsync<'a, M, S>
where
    M: Message,
    S: AsyncEncodeSink,
{ .. }

impl<'a, M, S> EncodeRawAsync<'a, M, S>
where
    M: Message,
    S: AsyncEncodeSink,
{ .. }

impl<M, S> Future for EncodeRawAsync<'_, M, S>
where
    M: Message,
    S: AsyncEncodeSink + Send,
{ .. }

/// CPU-backed [`AsyncEncodeSink`] adapter for an existing [`BufMut`].
#[derive(Debug)]
pub struct BufMutEncodeSink<'a, B> {
    buf: &'a mut B,
}

impl<'a, B> BufMutEncodeSink<'a, B> { .. }

impl<B> AsyncEncodeSink for BufMutEncodeSink<'_, B>
where
    B: BufMut + Send,
{ .. }

/// Encodes `message` into an asynchronous sink.
///
/// This helper preserves Prost's existing capacity check and length-delimited
/// framing behavior, then delegates the message body to
/// [`Message::encode_raw_async`].
pub async fn encode_message_to_sink<M, S>(
    message: &M,
    sink: &mut S,
    options: EncodeOptions,
) -> Result<(), S::Error>
where
    M: Message,
    S: AsyncEncodeSink + Send,
{ .. }

/// Engine that owns message transfer from a prost message into a destination.
///
/// The trait is intentionally separate from [`Message`], so generated structs
/// and existing synchronous call sites do not grow hardware-specific methods or
/// required async hooks.
pub trait EncodeEngine: Clone + Send + Sync + 'static { .. }

/// CPU-backed encode engine using prost's existing synchronous [`Message`] API.
#[derive(Clone, Copy, Debug, Default)]
pub struct CpuEngine;

/// Ready future returned by [`CpuEngine`].
#[derive(Debug)]
pub struct CpuEncode<B> {
    result: Option<Result<B, EncodeError>>,
}

impl<B> CpuEncode<B> { .. }

impl<B> Unpin for CpuEncode<B> {}

impl<B> Future for CpuEncode<B> { .. }

impl EncodeEngine for CpuEngine { .. }

/// Extension trait for owned asynchronous encoding of prost messages.
pub trait AsyncEncodeExt: Message + Sized + Send + 'static { .. }

impl<M> AsyncEncodeExt for M
where
    M: Message + Sized + Send + 'static,
{ .. }

