/// Mutable destination used by generated asynchronous Prost encoding.
///
/// The sink exposes a short-lived [`BufMut`] view for protobuf structure
/// writes, and a separate payload-copy hook for `string` / `bytes` field
/// contents. The default CPU sink copies payloads immediately; experimental
/// sinks can return [`Poll::Pending`] while an external copy engine initializes
/// the destination bytes.
pub trait AsyncEncodeSink {
    /// Error produced while starting or completing an asynchronous encode.
    type Error: Send + Sync + 'static;

    /// Borrowed protobuf byte sink for CPU-written keys, lengths, and scalars.
    type BufMut<'a>: BufMut + Send
    where
        Self: 'a;

    /// Per-payload state kept by poll-based generated encoders while a sink
    /// copy is pending.
    type PayloadState: Default + Send;

    /// Converts a Prost capacity error into this sink's error type.
    fn encode_error(error: EncodeError) -> Self::Error;

    /// Returns the byte sink used for CPU-written protobuf structure.
    fn buf_mut(&mut self) -> Self::BufMut<'_>;

    /// Copies a `string` or `bytes` payload into the destination.
    fn poll_put_payload(
        &mut self,
        payload: &[u8],
        state: Pin<&mut Self::PayloadState>,
        cx: &mut Context<'_>,
    ) -> Poll<Result<(), Self::Error>>;

    /// Future-shaped adapter around [`AsyncEncodeSink::poll_put_payload`].
    fn put_payload<'a>(&'a mut self, payload: &'a [u8]) -> PutPayload<'a, Self>
    where
        Self: Sized,
    {
        PutPayload::new(self, payload)
    }
}

/// Cursor for one generated-message poll encoder frame.
#[derive(Clone, Copy, Debug, Default, Eq, PartialEq)]
struct PollEncodeFrame {
    field: usize,
    index: usize,
    phase: u8,
}

/// Universal generated-message state for poll-based async encoding.
pub struct PollEncodeState<S: AsyncEncodeSink> {
    root: PollEncodeFrame,
    nested: Vec<PollEncodeFrame>,
    depth: usize,
    payload: S::PayloadState,
}

impl<S: AsyncEncodeSink> Default for PollEncodeState<S> {
    fn default() -> Self {
        Self {
            root: PollEncodeFrame::default(),
            nested: Vec::new(),
            depth: 0,
            payload: S::PayloadState::default(),
        }
    }
}

impl<S: AsyncEncodeSink> PollEncodeState<S> {
    #[inline]
    fn frame(&self) -> &PollEncodeFrame {
        if self.depth == 0 {
            &self.root
        } else {
            &self.nested[self.depth - 1]
        }
    }

    #[inline]
    fn frame_mut(&mut self) -> &mut PollEncodeFrame {
        if self.depth == 0 {
            &mut self.root
        } else {
            &mut self.nested[self.depth - 1]
        }
    }

    #[inline]
    pub fn clear(&mut self) {
        *self.frame_mut() = PollEncodeFrame::default();
        if self.depth == 0 {
            self.nested.clear();
        }
    }

    #[inline]
    pub fn field(&self) -> usize {
        self.frame().field
    }

    #[inline]
    pub fn advance_field(&mut self) {
        let frame = self.frame_mut();
        frame.field += 1;
        frame.index = 0;
        frame.phase = 0;
    }

    #[inline]
    pub fn index(&self) -> usize {
        self.frame().index
    }

    #[inline]
    pub fn set_index(&mut self, index: usize) {
        self.frame_mut().index = index;
    }

    #[inline]
    pub fn phase(&self) -> u8 {
        self.frame().phase
    }

    #[inline]
    pub fn set_phase(&mut self, phase: u8) {
        self.frame_mut().phase = phase;
    }

    #[inline]
    pub fn enter_nested(&mut self) {
        let nested_index = self.depth;
        if self.nested.len() == nested_index {
            self.nested.push(PollEncodeFrame::default());
        }
        self.depth += 1;
    }

    #[inline]
    pub fn leave_nested_pending(&mut self) {
        debug_assert!(self.depth > 0);
        self.depth -= 1;
    }

    #[inline]
    pub fn leave_nested_ready(&mut self) {
        debug_assert!(self.depth > 0);
        let nested_index = self.depth - 1;
        self.nested.truncate(nested_index);
        self.depth -= 1;
    }

