#[cfg(test)]
impl PendingYieldingProstPayloadCopy {
    fn new() -> Self {
        Self { yielded: false }
    }

    fn poll(
        &mut self,
        source: &[u8],
        buf: &mut EncodeBuffer,
        cx: &mut Context<'_>,
    ) -> Poll<Result<(), Status>> {
        if !self.yielded {
            self.yielded = true;
            cx.waker().wake_by_ref();
            return Poll::Pending;
        }

        buf.as_encode_buf().put_slice(source);
        Poll::Ready(Ok(()))
    }
}

